// Analyze question and determine optimal top_k
const question = $json.body.chatInput || '';
const articleSlug = $json.body.articleSlug || null;

if (!question.trim()) {
  throw new Error('chatInput is required and cannot be empty');
}

const lowerQ = question.toLowerCase();

let top_k = 10;
if (lowerQ.includes('szczegół') || lowerQ.includes('jak') || lowerQ.includes('porówn')) {
  top_k = 15;
} else if (lowerQ.includes('przykład') || lowerQ.includes('lista')) {
  top_k = 12;
}

return {
  json: {
    query: question,
    top_k: top_k,
    articleSlug: articleSlug
  }
};

// Format RAG API results for LLM context
const response = $input.item.json;
const originalQuestion = $('Code: Analyze Question').item.json.query;

if (!response || !response.results || response.results.length === 0) {
  return {
    json: {
      context: 'Brak wyników. System RAG nie znalazł odpowiednich artykułów.',
      chatInput: originalQuestion,
      hasResults: false,
      resultCount: 0,
      results: [],
      originalQuestion
    }
  };
}

const results = response.results;

let context = `Znaleziono ${results.length} wyników z bazy wiedzy:\n\n`;
const formattedResults = [];

results.forEach((hit, index) => {
  context += `--- Wynik ${index + 1} (Score: ${(hit.score * 100).toFixed(1)}%) ---\n`;
  context += `Tytuł: ${hit.title || 'Brak tytułu'}\n`;
  context += `URL: ${hit.url || ''}\n`;
  context += `Typ sekcji: ${hit.section_type || 'content'}\n`;

  if (hit.publication_date) {
    context += `Data publikacji: ${hit.publication_date}\n`;
  }

  if (hit.tags && hit.tags.length > 0) {
    context += `Tagi: ${hit.tags.join(', ')}\n`;
  }

  if (hit.categories && hit.categories.length > 0) {
    context += `Kategorie: ${hit.categories.join(', ')}\n`;
  }

  context += `\nTreść:\n${hit.text || ''}\n\n`;

  formattedResults.push({
    title: hit.title || 'Brak tytułu',
    url: hit.url || '',
    score: hit.score,
    text: hit.text || '',
    section_type: hit.section_type || 'content'
  });
});

return {
  json: {
    context,
    chatInput: originalQuestion,
    hasResults: true,
    resultCount: results.length,
    results: formattedResults,
    originalQuestion
  }
};
